/// <summary>
/// CB233_TOReceiptDetails custom service multi TO receipts request contract
/// </summary>
[DataContractAttribute]
class METInventTransferOrderReceiveRequestMultiContract
{
    private List    receipts;

}

Method.Source:
    /// <summary>
    /// List of single TO receipt request contract
    /// </summary>
    /// <param name = "_receipts">Set list of single TO receipt request contract</param>
    /// <returns>Get list of single TO receipt request contract</returns>
    [DataMemberAttribute("Receipts"),
    DataCollection(Types::Class, classStr(METInventTransferOrderReceiveRequestSingleContract)),
    AifCollectionTypeAttribute('_receipts', Types::Class, classStr(METInventTransferOrderReceiveRequestSingleContract)),
    AifCollectionTypeAttribute('return', Types::Class, classStr(METInventTransferOrderReceiveRequestSingleContract))]
    public List parmReceipts(List _receipts = receipts)
    {
        if (!prmIsDefault(_receipts))
        {
            receipts = _receipts;
        }

        return receipts;
    }
